package main

import (
	"embed"
	"html/template"
	"log"
	"net/http"
	"sort"
	"strings"
)

//go:embed templates
var templateFS embed.FS

var funcs = template.FuncMap{
	"inc":  func(i int) int { return i + 1 },
	"pips": pips,
}

// Each page defines "body", so each gets its own template set.
var (
	homeTmpl  = mustParse("templates/layout.html", "templates/home.html")
	lobbyTmpl = mustParse("templates/layout.html", "templates/lobby.html")
	roomTmpl  = mustParse("templates/layout.html", "templates/room.html", "templates/panel.html")
	panelTmpl = mustParse("templates/room.html", "templates/panel.html")
)

func mustParse(files ...string) *template.Template {
	t, err := template.New("layout").Funcs(funcs).ParseFS(templateFS, files...)
	if err != nil {
		log.Fatalf("parse templates %v: %v", files, err)
	}
	return t
}

func render(w http.ResponseWriter, status int, t *template.Template, name string, data any) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	if err := t.ExecuteTemplate(w, name, data); err != nil {
		log.Printf("render %s: %v", name, err)
	}
}

// pips returns the nine cells of a die face, true where a pip belongs.
func pips(value int) []bool {
	layouts := map[int][]int{
		1: {4}, 2: {0, 8}, 3: {0, 4, 8}, 4: {0, 2, 6, 8}, 5: {0, 2, 4, 6, 8}, 6: {0, 2, 3, 5, 6, 8},
	}
	if value < 1 || value > 6 {
		value = 1
	}
	out := make([]bool, 9)
	for _, i := range layouts[value] {
		out[i] = true
	}
	return out
}

/* ------------------------------------------------------------ view models --- */

// Everything below shapes room state for a template. Keeping the arithmetic
// here rather than in the markup means the templates stay readable and the
// logic stays testable.

type homeView struct {
	User         *D3bitUser
	Top          []*Standing
	MyRank       int
	Lobbies      []lobbyView
	PlayerCounts []int
	Letters      []string // the wordmark, one span per letter
	GoogleURL    string
	Error        string
	LoginMsg     string
}

type lobbyView struct {
	Code       string
	Players    int
	MaxPlayers int
}

type choiceView struct {
	Index  int
	Letter string
	Text   string
	Class  string
}

type questionView struct {
	Index      int
	Number     int
	Prompt     string
	Choices    []choiceView
	Answered   bool
	WasCorrect bool
	Seeded     bool
	Fact       string
	Source     string
	SourceURL  string
	Waiting    int
	Pct        int
}

type reviewView struct {
	Prompt string
	Answer string
	Fact   string
	Source string
}

type roomView struct {
	Room        *Room
	Me          string
	CalaEnabled bool
	Flash       string
	FullPage    bool // the whole room page, not a poll: no out-of-band roster

	Picking       string
	PickerName    string
	IsTopicPicker bool
	IsMyPick      bool
	IHaveRolled   bool
	RollWinner    string // set once every die has landed
	FillPct       int

	Entities    []string // what the graph resolved the topic to
	SubTopics   []subTopicView
	Suggestions []string
	Question    *questionView
	Ranked      []*Player
	Review      []reviewView
	HasURLs     bool
}

type subTopicView struct {
	SubTopic
	OwnerName string
}

// buildRoomView snapshots the room for one player. The caller must not hold
// the room lock; this takes it.
func (s *Server) buildRoomView(room *Room, me string, flash string) *roomView {
	room.mu.Lock()
	defer room.mu.Unlock()
	return s.roomViewLocked(room, me, flash)
}

func (s *Server) roomViewLocked(room *Room, me, flash string) *roomView {
	room.tick()
	v := &roomView{
		Room:        room,
		Me:          me,
		CalaEnabled: s.cala.Enabled(),
		Flash:       flash,
		FillPct:     len(room.Players) * 100 / max(1, room.MaxPlayer),
	}

	switch room.Phase {
	case PhaseTopic:
		v.Picking = room.TopicPicker()
	case PhaseSubTopics:
		v.Picking = room.NextSubTopicPicker()
	}
	v.IsTopicPicker = room.Phase == PhaseTopic && room.TopicPicker() == me
	v.IsMyPick = room.Phase == PhaseSubTopics && room.NextSubTopicPicker() == me
	if p := room.find(v.Picking); p != nil {
		v.PickerName = p.DisplayName
	} else {
		v.PickerName = "the next player"
	}
	if p := room.find(me); p != nil {
		v.IHaveRolled = p.Roll != 0
	}
	if room.Settled() && len(room.Order) > 0 {
		if p := room.find(room.Order[0]); p != nil {
			v.RollWinner = p.DisplayName
		}
	}

	if room.graph != nil {
		for _, e := range room.graph.Entities {
			v.Entities = append(v.Entities, e.Name)
		}
	} else if room.Topic != "" && !s.cala.Enabled() {
		for _, e := range offlineEntitiesFor(room.Topic) {
			v.Entities = append(v.Entities, e.name)
		}
	}

	for _, st := range room.SubTopics {
		sv := subTopicView{SubTopic: st}
		if owner := room.find(st.ClaimedBy); owner != nil {
			sv.OwnerName = owner.DisplayName
		}
		v.SubTopics = append(v.SubTopics, sv)
	}

	if room.Phase == PhaseQuiz && room.Current < len(room.Questions) {
		v.Question = questionViewFor(room, room.Questions[room.Current], me)
	}

	if room.Phase == PhaseResults {
		v.Ranked = append([]*Player{}, room.Players...)
		sort.SliceStable(v.Ranked, func(i, j int) bool { return v.Ranked[i].Score > v.Ranked[j].Score })
		for _, q := range room.Questions {
			answer := ""
			if q.Answer >= 0 && q.Answer < len(q.Options) {
				answer = q.Options[q.Answer]
			}
			src := q.Source
			if q.SourceURL != "" {
				src = q.SourceURL
				v.HasURLs = true
			}
			v.Review = append(v.Review, reviewView{Prompt: q.Prompt, Answer: answer, Fact: q.Fact, Source: src})
		}
	}
	return v
}

func questionViewFor(room *Room, q *Question, me string) *questionView {
	qv := &questionView{
		Index:     q.Index,
		Number:    q.Index + 1,
		Prompt:    q.Prompt,
		Seeded:    q.SeededBy == me,
		Fact:      q.Fact,
		Source:    q.Source,
		SourceURL: q.SourceURL,
		Waiting:   len(room.Players) - len(q.Answers),
		Pct:       q.Index * 100 / max(1, len(room.Questions)),
	}
	if p := room.find(me); p != nil {
		qv.Answered = p.answered[q.Index]
	}

	myChoice := -1
	for _, a := range q.Answers {
		if a.PlayerID == me {
			myChoice = a.Choice
			qv.WasCorrect = a.Correct
		}
	}

	for i, opt := range q.Options {
		c := choiceView{Index: i, Letter: string(rune('A' + i)), Text: opt}
		// The right answer is only ever sent to a player who has committed.
		if qv.Answered {
			switch {
			case i == q.Answer:
				c.Class = "correct"
			case i == myChoice:
				c.Class = "wrong"
			}
		}
		qv.Choices = append(qv.Choices, c)
	}
	return qv
}

func titleCode(s string) string { return strings.ToUpper(strings.TrimSpace(s)) }
// deez.win — a multiplayer quiz where the questions come from a verified
// entity graph rather than from a language model.
//
// The loop: players join a room, dice decide the order, the winner picks an
// overall topic, and everyone else claims one of the top five sub-topics Cala
// actually holds data for. Questions are built from those axes.
package main

import (
	"embed"
	"flag"
	"io/fs"
	"log"
	"net/http"
	"os"
	"time"
)

//go:embed static
var staticFS embed.FS

func main() {
	addr := flag.String("addr", ":8080", "listen address")
	d3bitURL := flag.String("d3bit", envOr("D3BIT_URL", "https://api.d3bit.com"), "D3BIT API base URL")
	origin := flag.String("origin", "", "public origin for auth callbacks (default http://localhost<addr>)")
	statePath := flag.String("leaderboard", defaultLeaderboardPath(), "path to the persisted leaderboard")
	devAuth := flag.Bool("dev-auth", false, "use local stand-in sessions instead of D3BIT (local development only)")
	probe := flag.String("probe", "", "resolve a topic against Cala, print what a round would use, and exit")
	flag.Parse()

	cala := NewCala(os.Getenv("CALA_API_KEY"))
	if *probe != "" {
		os.Exit(runProbe(cala, *probe))
	}

	var auth sessionSource = NewAuth(*d3bitURL)
	if *devAuth {
		auth = NewDevAuth()
		log.Printf("auth: DEV MODE — anyone can mint a session. Never expose this publicly.")
	} else {
		log.Printf("auth: d3bit %s", *d3bitURL)
	}

	if *origin == "" {
		*origin = "http://localhost" + *addr
	}

	board := NewLeaderboard(*statePath)
	log.Printf("leaderboard: %s", *statePath)

	srv := &Server{
		auth:     auth,
		board:    board,
		d3bitURL: *d3bitURL,
		origin:   *origin,
		store:    NewStore(),
		cala:     cala,
	}

	mux := http.NewServeMux()
	srv.Routes(mux)

	sub, err := fs.Sub(staticFS, "static")
	if err != nil {
		log.Fatalf("static assets: %v", err)
	}
	mux.Handle("GET /", http.FileServer(http.FS(sub)))

	if cala.Enabled() {
		log.Printf("cala: enabled")
		cala.Warm(CalaTopicSuggestions())
	} else {
		log.Printf("cala: no CALA_API_KEY — running on offline fixtures")
	}
	log.Printf("listening on http://localhost%s", *addr)

	server := &http.Server{
		Addr:              *addr,
		Handler:           mux,
		ReadHeaderTimeout: 10 * time.Second,
	}
	log.Fatal(server.ListenAndServe())
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

