func pips(value int) []bool {
	layouts := map[int][]int{
		1: {4}, 2: {0, 8}, 3: {0, 4, 8}, 4: {0, 2, 6, 8}, 5: {0, 2, 4, 6, 8}, 6: {0, 2, 3, 5, 6, 8},
	}
	if value < 1 || value > 6 {
		value = 1
	}
	out := make([]bool, 9)
	for _, i := range layouts[value] {
		out[i] = true
	}
	return out
}

