<div class="topbar">
  <a class="brand" href="/" aria-label="deez.win home"><i class="brand-die"></i>deez.win</a>
  <div class="row">
    <button type="button" class="ghost small" data-mute aria-label="Toggle sound">🔊</button>
    {{with .User}}<span class="tag {{if not .IsAnon}}live{{end}}">{{.DisplayName}}{{if .IsAnon}} · guest{{end}}</span>{{end}}
  </div>
</div>

{{with .Error}}<div class="banner danger">{{.}}</div>{{end}}

<section class="hero lobby-hero">
  <span class="eyebrow">Lobby</span>
  <h1 class="hero-title">Start a table or <em>join one</em>.</h1>
</section>

<div class="lobby-actions">
  <section class="card hero-card">
    <label class="field">Create a lobby</label>
    <form method="post" action="/rooms" class="stack">
      <div class="stepper" role="radiogroup" aria-label="Number of players">
        {{range $n := .PlayerCounts}}
          <label class="seg">
            <input type="radio" name="max_players" value="{{$n}}" {{if eq $n 3}}checked{{end}}>
            <span>{{$n}}</span>
          </label>
        {{end}}
      </div>
      <div class="row wrap">
        <button class="primary" name="public" value="0">Private lobby</button>
        <button class="ghost" name="public" value="1">Public lobby</button>
      </div>
    </form>
  </section>

  <section class="card">
    <label class="field">Join with a code</label>
    <form method="post" action="/join" class="stack">
      <input type="text" class="code" name="code" maxlength="4" placeholder="CODE"
             autocomplete="off" required pattern="[A-Za-z0-9]{4}" aria-label="Room code">
      <button>Join lobby</button>
    </form>
  </section>
</div>

<div class="grid3 lobby-grid">
  <!-- Polled separately so a lobby appearing elsewhere shows up here without
       touching the rest of the page. -->
  <div class="card" hx-get="/lobbies" hx-trigger="every 5s" hx-target="this" hx-swap="innerMorph">
    {{template "lobbies" .}}
  </div>
  <div class="card" id="leaderboard" hx-get="/leaderboard" hx-trigger="every 10s" hx-target="this" hx-swap="innerMorph">
    {{template "leaderboard" .}}
  </div>
  <div class="card" id="account">{{template "account" .}}</div>
</div>

<p class="footer">DATA BY CALA · IMAGES &amp; SOUND BY FAL.AI</p>
{{end}}

{{define "lobbies"}}
<label class="field">Public lobbies</label>
{{if .Lobbies}}
  {{range .Lobbies}}
    <div class="lobby-item">
      <span class="pixel small">{{.Code}}</span>
      <span class="muted small">{{.Players}}/{{.MaxPlayers}} players</span>
      <form method="post" action="/join"><input type="hidden" name="code" value="{{.Code}}"><button>Join</button></form>
    </div>
  {{end}}
{{else}}
  <p class="muted small tight">Nobody is waiting right now. Make a public lobby and it shows up here.</p>
{{end}}
{{end}}

{{define "account"}}
<label class="field">Account</label>
{{if and .User (not .User.IsAnon)}}
  <p class="small">Signed in as <strong>{{or .User.Email .User.DisplayName}}</strong>.</p>
  <form method="post" action="/logout"><button class="ghost">Log out</button></form>
{{else}}
  <p class="small muted">You're a guest. Sign in to keep your score on the board.</p>
  <form class="stack" hx-post="/login" hx-target="#account" hx-swap="innerHTML">
    <input type="email" name="email" placeholder="you@example.com" class="plain" required>
